out = root/'docs'/'preview-estatico';out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox'])
    for width in [390,768,1440]:
        page=browser.new_page(viewport={'width':width,'height':900},device_scale_factor=1)
        page.set_content(html,wait_until='load')
        result=page.evaluate('''() => ({scrollWidth:document.documentElement.scrollWidth, viewport:window.innerWidth, title:document.querySelector('.studio-intro h1').getBoundingClientRect().width, em:document.querySelector('.studio-intro em').scrollWidth})''')
        page.screenshot(path=str(out/f'home-{width}.png'),full_page=True)
        print(width,result)
        page.close()
    browser.close()
print('ATENÇÃO: prévias de HTML/CSS estático, não capturas da aplicação React.')
